import SwiftUI

/// FRO-394 background-resilience drill panel: recovery status, the jetsam
/// ballast instrument, and the on-device drill matrix so the field session is
/// turnkey. Spike UI — function over polish.
struct DrillsScreen: View {
    @Bindable var model: HarnessModel
    @Environment(\.dismiss) private var dismiss

    var body: some View {
        NavigationStack {
            List {
                Section("Status") {
                    HarnessListRow("Launch", model.recoveryStatus)
                    HarnessListRow("Run active", model.isRunning ? "yes" : "no")
                    HarnessListRow("Ballast", "\(model.ballastMB) MB")
                }
                Section("Instruments") {
                    Button("Add \(HarnessModel.ballastChunkMB) MB ballast (jetsam drill)") {
                        model.addBallast()
                    }
                    .disabled(!model.isRunning)
                    Text("Ballast needs a running run so footprint_mb and the kill land in the CSV.")
                        .font(.footnote)
                        .foregroundStyle(.secondary)
                }
                Section("Drill matrix (run each with a run active)") {
                    Text("""
                    1. LOCK 30 MIN — start a run, lock the phone, walk/ride \
                    30 min, unlock. Pass: `fix` rows continue while locked \
                    (scene=background brackets the segment).

                    2. FORCE-QUIT → RELAUNCH — swipe the app away mid-run, \
                    reopen it. Pass: Status shows "recovered", new CSV has \
                    `recovered_relaunch prior_log=…`, gap ≤5 s in the old CSV.

                    3. JETSAM — mid-run, press ballast repeatedly until iOS \
                    kills the app. Leave the phone alone, screen locked, and \
                    keep moving. Pass: the app relaunches itself on a location \
                    event and the new CSV starts with `recovered_relaunch`. \
                    Note the wake latency (gap between CSVs).

                    4. AIRPLANE MODE — toggle it mid-run for 5 min. Pass: \
                    `fix` rows continue (GPS has no network dependency).

                    5. PHONE CALL — receive/place a call mid-run. Pass: no \
                    gap in `fix` rows.

                    6. 4 H SOAK — start a run, lock, pocket the phone for a \
                    long walk/turbo session. Pass: no silent stoppage; any \
                    gap >10 s in `fix` rows is a finding (iOS 17+ silent-stop \
                    reports, forums 776698/767460).

                    Share each CSV via the LOG button; analyze with \
                    scripts/analyze-s1.py.
                    """)
                    .font(.footnote)
                    .foregroundStyle(.secondary)
                }
            }
            .navigationTitle("S2 Resilience Drills")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Close") { dismiss() }
                }
            }
        }
        .preferredColorScheme(.dark)
        // Opening this panel mid-run changes the lit-pixel budget — mark the
        // window in the CSV so analysis can exclude it.
        .onAppear { model.logRunEvent("drills_open") }
        .onDisappear { model.logRunEvent("drills_closed") }
    }
}

#Preview {
    DrillsScreen(model: HarnessModel())
}

