import SwiftUI

/// 0.1.0 spike harness (FRO-391): a single-screen, mostly-black app whose job is
/// to produce the go/no-go battery/thermal/accuracy numbers on real rides.
/// Throwaway code — the Rouleur app target must never depend on it.
@main
struct HarnessApp: App {
    @Environment(\.scenePhase) private var scenePhase
    // resumingAtLaunch: FRO-394 — a killed run auto-resumes before first frame.
    @State private var model = HarnessModel.resumingAtLaunch()
    @State private var workout = WorkoutController()
    // Single owner of launch-arg parsing; --lab-autorun implies the lab open.
    private let openLabAtLaunch = CommandLine.arguments.contains("--open-lab")
        || CommandLine.arguments.contains("--lab-autorun")
    private let openDrillsAtLaunch = CommandLine.arguments.contains("--open-drills")

    var body: some Scene {
        WindowGroup {
            HarnessScreen(model: model, workout: workout,
                          openLabAtLaunch: openLabAtLaunch,
                          openDrillsAtLaunch: openDrillsAtLaunch)
                .task {
                    // Recovery first, every launch — the crash drill (S2)
                    // relies on this running before anything else.
                    await workout.attemptRecovery()
                    await runLaunchArguments()
                }
                // Scene transitions bracket the locked-phone experiments in
                // the log, so heartbeat/LA rows can be read against them.
                // Gated so pure S1 launches never touch the experiment log.
                .onChange(of: scenePhase) { _, phase in
                    let label = String(describing: phase)
                    if workout.isInstrumenting {
                        workout.log.log("scene", label)
                    }
                    // FRO-394: bracket locked-phone segments in the S1 CSV.
                    model.logScene(label)
                }
        }
    }

    /// Simulator/automation hooks for the smoke run (see verify notes in the PR):
    /// `--autostart` begins an S1 run at launch; `--exercise-toggles` flips each
    /// toggle mid-run to prove the run and logger survive them; `--lab-autorun`
    /// (with `--open-lab`) drives the tap-free part of the S2 lab: start the
    /// Live Activity, then surface the HealthKit auth sheet; `--open-drills`
    /// opens the FRO-394 drill panel (manual drills — no autorun counterpart).
    private func runLaunchArguments() async {
        let arguments = CommandLine.arguments
        if arguments.contains("--lab-autorun") {
            workout.startLiveActivity()
            await workout.requestAuthorization()
            return
        }
        guard arguments.contains("--autostart") else { return }
        model.start()
        guard arguments.contains("--exercise-toggles") else { return }
        try? await Task.sleep(for: .seconds(12))
        model.theme = .white
        try? await Task.sleep(for: .seconds(2))
        model.refreshMode = .high
        try? await Task.sleep(for: .seconds(2))
        model.backend = .legacyManager
    }
}

