import SwiftUI

/// Shared label/value row for the harness's spike List panels (drills, lab).
struct HarnessListRow: View {
    let label: String
    let value: String

    init(_ label: String, _ value: String) {
        self.label = label
        self.value = value
    }

    var body: some View {
        HStack {
            Text(label)
            Spacer()
            Text(value).foregroundStyle(.secondary).font(.body.monospaced())
        }
    }
}

import CoreLocation
import UIKit

/// CSV logger for the S1 field protocol. One file per run in Documents, header
/// metadata as `#`-prefixed lines, a sample row every 10 s, and an event row for
/// every mid-run toggle so FRO-393's A/B analysis can segment the data.
///
/// A silent logging gap would corrupt the go/no-go number, so every write failure
/// is surfaced to the UI via `onError` instead of being swallowed.
@MainActor
final class HarnessLogger {
    static let sampleInterval: Duration = .seconds(10)

    let fileURL: URL
    var onError: ((String) -> Void)?

    private var handle: FileHandle?
    private var tickTask: Task<Void, Never>?
    private var latestLocation: CLLocation?
    private var totalSamples = 0
    private var samplesAtLastRow = 0
    private var lastSync = Date.distantPast

    // Shared with ExperimentLog so S1 and S2 timestamps always join.
    static let timestampFormatter = ISO8601DateFormatter()

    init?(metadata: [(String, String)]) {
        let name = "harness-\(Self.timestampFormatter.string(from: .now)).csv"
        let documents = URL.documentsDirectory
        fileURL = documents.appending(path: name)

        var header = metadata
            .map { "# \($0.0)=\($0.1)" }
            .joined(separator: "\n")
        header += "\nrow_type,timestamp,battery_pct,battery_state,thermal,brightness,lat,lon,h_acc_m,speed_mps,samples_since_last,samples_total,footprint_mb,event\n"

        guard FileManager.default.createFile(atPath: fileURL.path, contents: Data(header.utf8)),
              let handle = try? FileHandle(forWritingTo: fileURL),
              (try? handle.seekToEnd()) != nil else {
            return nil
        }
        self.handle = handle
    }

    func start() {
        guard tickTask == nil else { return }
        tickTask = Task { [weak self] in
            while !Task.isCancelled {
                self?.writeRow(type: "sample", event: "")
                try? await Task.sleep(for: Self.sampleInterval)
            }
        }
    }

    func stop() {
        writeRow(type: "event", event: "stop")
        tickTask?.cancel()
        tickTask = nil
        try? handle?.close()
        handle = nil
    }

    func updateLatest(location: CLLocation, totalSamples: Int) {
        latestLocation = location
        self.totalSamples = totalSamples
        // FRO-394: a `fix` row per GPS fix makes the CSV the minimal
        // append-only journal — after a kill, data loss is the gap between
        // the last row and the kill. Writes hit the fd directly (no
        // user-space buffer), so force-kill/jetsam loses nothing; the
        // periodic fsync in writeRow additionally bounds loss to ≤5 s
        // through an OS crash. (Not power-loss-proof — that would need
        // F_FULLFSYNC, which the real RideJournal should decide about.)
        writeRow(type: "fix", event: "")
    }

    func logEvent(_ event: String) {
        writeRow(type: "event", event: event)
        try? handle?.synchronize()
        lastSync = .now
    }

    /// `fix` rows are slim: they run at GPS rate and only exist to bound data
    /// loss, so they skip every device probe (battery/brightness/footprint/
    /// thermal) and leave `samples_since_last` empty — that column means
    /// "fixes since the previous 10 s sample row" and only sample rows may
    /// read or reset its baseline (FRO-393 derives GPS cadence from it).
    private func writeRow(type: String, event: String) {
        let slim = type == "fix"
        let batteryPct = slim ? "" : DeviceReadings.batteryPercentText() ?? "" // empty on simulator/unknown
        let brightness = slim ? "" : activeScreenBrightness().map { String(format: "%.2f", $0) } ?? ""
        let location = latestLocation
        let coordinates = location.map { ($0.coordinate.latitude, $0.coordinate.longitude) }
        let footprint = slim ? "" : Self.memoryFootprintBytes().map { String(format: "%.1f", Double($0) / 1_048_576) } ?? ""

        let fields: [String] = [
            type,
            Self.timestampFormatter.string(from: .now),
            batteryPct,
            slim ? "" : batteryStateLabel(UIDevice.current.batteryState),
            slim ? "" : ProcessInfo.processInfo.thermalState.csvLabel,
            brightness,
            coordinates.map { String(format: "%.6f", $0.0) } ?? "",
            coordinates.map { String(format: "%.6f", $0.1) } ?? "",
            location.map { String(format: "%.1f", $0.horizontalAccuracy) } ?? "",
            location.map { String(format: "%.2f", $0.speed) } ?? "",
            slim ? "" : String(totalSamples - samplesAtLastRow),
            String(totalSamples),
            footprint,
            event,
        ]
        if !slim { samplesAtLastRow = totalSamples }

        do {
            try handle?.write(contentsOf: Data((fields.joined(separator: ",") + "\n").utf8))
        } catch {
            onError?("Log write failed: \(error.localizedDescription)")
        }
        // Fsync cadence lives here so any row type drives it — a GPS stall
        // must not also stall durability (the stall's sample rows are the
        // evidence of the outage).
        if Date.now.timeIntervalSince(lastSync) > 5 {
            lastSync = .now
            try? handle?.synchronize()
        }
    }

    private func activeScreenBrightness() -> CGFloat? {
        let scene = UIApplication.shared.connectedScenes
            .compactMap { $0 as? UIWindowScene }
            .first { $0.activationState == .foregroundActive }
        return scene?.screen.brightness
    }

    private func batteryStateLabel(_ state: UIDevice.BatteryState) -> String {
        switch state {
        case .unplugged: "unplugged"
        case .charging: "charging"
        case .full: "full"
        default: "unknown"
        }
    }

    private static func memoryFootprintBytes() -> UInt64? {
        var info = task_vm_info_data_t()
        var count = mach_msg_type_number_t(
            MemoryLayout<task_vm_info_data_t>.size / MemoryLayout<integer_t>.size
        )
        let result = withUnsafeMutablePointer(to: &info) {
            $0.withMemoryRebound(to: integer_t.self, capacity: Int(count)) {
                task_info(mach_task_self_, task_flavor_t(TASK_VM_INFO), $0, &count)
            }
        }
        guard result == KERN_SUCCESS else { return nil }
        return info.phys_footprint
    }
}

