import CoreLocation
import UIKit

enum HarnessTheme: String, CaseIterable, Identifiable {
    case black, white
    var id: String { rawValue }
    var label: String { self == .black ? "BLK" : "WHT" }
}

enum RefreshMode: String, CaseIterable, Identifiable {
    /// ~10 Hz content cadence — the product hypothesis (8–15 Hz floor).
    case low
    /// 60 Hz comparison arm for the FRO-393 A/B.
    case high

    var id: String { rawValue }
    var period: TimeInterval { self == .low ? 0.1 : 1.0 / 60.0 }
    var label: String { self == .low ? "10 Hz" : "60 Hz" }
}

@MainActor @Observable
final class HarnessModel {
    // Mid-run toggles — each change is an event row in the CSV so the A/B
    // analysis can segment a single ride.
    var theme: HarnessTheme = .black {
        didSet { logger?.logEvent("theme=\(theme.rawValue)") }
    }
    var refreshMode: RefreshMode = .low {
        didSet { logger?.logEvent("refresh=\(refreshMode.rawValue)") }
    }
    var backend: LocationBackend = .liveUpdates {
        didSet {
            logger?.logEvent("backend=\(backend.rawValue)")
            if isRunning { startFeed() } // restart feed only; run + logger keep going
        }
    }

    private(set) var isRunning = false
    private(set) var startDate: Date?
    private(set) var gpsSampleCount = 0
    private(set) var loggerError: String?
    private(set) var logFileURL: URL?

    // Display strings, formatted here once per change rather than in the view —
    // the dashboard repaints at up to 60 Hz while GPS arrives at 1–2 Hz and
    // battery/thermal change on the order of minutes.
    private(set) var speedText = "--.-"
    /// Numeric twin of `speedText`, for the hero arc (0 when no valid speed).
    private(set) var speedKmh: Double = 0
    private(set) var distanceText = "0.00"
    private(set) var accuracyText = "--"
    /// Whether the latest fix carried a valid horizontal accuracy — the view's
    /// GPS indicator reads this, not the display-string sentinel.
    private(set) var hasFix = false
    private(set) var batteryText = "--"
    private(set) var thermalText = ProcessInfo.processInfo.thermalState.shortLabel

    private var logger: HarnessLogger?
    private var feedTask: Task<Void, Never>?
    private var lastLocation: CLLocation?
    private var distanceMeters: Double = 0

    // FRO-394 background-resilience instrumentation.
    /// Held for the run's lifetime so location keeps flowing while locked
    /// (WWDC23: recreate immediately on any relaunch, done in `resumingAtLaunch`).
    private var backgroundSession: CLBackgroundActivitySession?
    /// Set on start, cleared on clean stop — survives force-kill/jetsam, which
    /// is how a relaunch knows to auto-resume. `runStartedKey` bounds it: a
    /// marker older than `markerExpiryHours` is stale (forgotten STOP), not a
    /// ride to resume.
    private static let runActiveKey = "s1.runActive"
    private static let currentLogKey = "s1.currentLog"
    private static let runStartedKey = "s1.runStarted"
    private static let markerExpiryHours: Double = 8
    private(set) var recoveryStatus = "cold launch"
    /// Jetsam-drill ballast: incompressible dirty pages the system can only
    /// reclaim by killing us. ~200 MB per press, freed on STOP.
    private var ballastChunks: [Data] = []
    var ballastMB: Int { ballastChunks.count * Self.ballastChunkMB }
    static let ballastChunkMB = 200

    init() {
        // Device-wide monitoring switch, owned here rather than by the logger so
        // the dashboard shows battery before the first run starts.
        UIDevice.current.isBatteryMonitoringEnabled = true
        // Fire-and-forget: the weak-self binding ends the loop if the model
        // ever deallocates, so no stored reference or deinit cancellation is
        // needed (strict concurrency rejects the latter for MainActor state).
        Task { [weak self] in
            while let self, !Task.isCancelled {
                self.updateDeviceReadings()
                try? await Task.sleep(for: .seconds(5))
            }
        }
    }

    /// Factory for the app entry point: recreates a killed run's state before
    /// the first frame, per the WWDC23 requirement that liveUpdates iteration
    /// and a fresh CLBackgroundActivitySession be rebuilt immediately on any
    /// relaunch. This must run at process start (a @State initializer), not in
    /// `.task` — a jetsam relaunch triggered by a location event launches the
    /// app into the background with no window, where `.task` never fires.
    static func resumingAtLaunch() -> HarnessModel {
        let model = HarnessModel()
        let defaults = UserDefaults.standard
        guard defaults.bool(forKey: runActiveKey) else { return model }
        let started = defaults.object(forKey: runStartedKey) as? Date
        guard let started,
              Date.now.timeIntervalSince(started) < Self.markerExpiryHours * 3600 else {
            // Forgotten STOP, not a ride: don't burn GPS/battery forever.
            defaults.set(false, forKey: runActiveKey)
            model.recoveryStatus = "stale marker expired (no auto-resume)"
            return model
        }
        model.start(recoveredFrom: defaults.string(forKey: currentLogKey) ?? "unknown")
        return model
    }

    func start(recoveredFrom priorLog: String? = nil) {
        guard !isRunning else { return }
        isRunning = true
        startDate = .now
        gpsSampleCount = 0
        lastLocation = nil
        distanceMeters = 0
        speedText = "--.-"
        speedKmh = 0
        distanceText = "0.00"
        accuracyText = "--"
        hasFix = false
        loggerError = nil

        UIApplication.shared.isIdleTimerDisabled = true

        let device = UIDevice.current
        logger = HarnessLogger(metadata: [
            ("device", device.model),
            ("os", "\(device.systemName) \(device.systemVersion)"),
            ("app_version", Bundle.main.infoDictionary?["CFBundleShortVersionString"] as? String ?? "?"),
            ("theme", theme.rawValue),
            ("refresh", refreshMode.rawValue),
            ("backend", backend.rawValue),
            // Restyles change the lit-pixel budget (the S1 dependent
            // variable); bump this tag whenever the dashboard's visual
            // weight changes so runs stay segmentable across UI versions.
            ("ui", "soft-instrument-v1"),
            ("drills", "v1"),
            ("recovered_from", priorLog ?? ""),
        ])
        if let logger {
            logFileURL = logger.fileURL
            logger.onError = { [weak self] message in self?.loggerError = message }
            logger.start()
            if let priorLog {
                logger.logEvent("recovered_relaunch prior_log=\(priorLog)")
                recoveryStatus = "recovered (prior: \(priorLog))"
            }
            // Marker survives force-kill/jetsam; only a clean stop clears it.
            // Set only on a successful logger so a disk-full launch can't
            // wedge itself into a retry-forever loop.
            let defaults = UserDefaults.standard
            defaults.set(true, forKey: Self.runActiveKey)
            defaults.set(logger.fileURL.lastPathComponent, forKey: Self.currentLogKey)
            defaults.set(Date.now, forKey: Self.runStartedKey)
        } else {
            loggerError = "Could not create log file"
        }

        backgroundSession = CLBackgroundActivitySession()
        startFeed()
    }

    func stop() {
        guard isRunning else { return }
        feedTask?.cancel()
        feedTask = nil
        // Free the jetsam ballast so it can't contaminate the next run's
        // footprint/energy numbers; log while the logger still exists.
        if !ballastChunks.isEmpty {
            logger?.logEvent("ballast_cleared")
            ballastChunks.removeAll()
        }
        logger?.stop()
        logger = nil
        backgroundSession?.invalidate()
        backgroundSession = nil
        UserDefaults.standard.set(false, forKey: Self.runActiveKey)
        UIApplication.shared.isIdleTimerDisabled = false
        isRunning = false
    }

    /// Scene transitions bracket the locked-phone drills in the CSV so gap
    /// analysis can tell "locked" from "GPS outage".
    func logScene(_ label: String) {
        logRunEvent("scene=\(label)")
    }

    /// Drill instrumentation into the run's CSV (no-op when not running).
    func logRunEvent(_ event: String) {
        guard isRunning else { return }
        logger?.logEvent(event)
    }

    /// Jetsam drill: each press dirties ~200 MB the system can only reclaim
    /// by killing the app. Watch footprint_mb climb in the CSV until jetsam.
    func addBallast() {
        var chunk = Data(count: Self.ballastChunkMB * 1_048_576)
        chunk.withUnsafeMutableBytes { raw in
            // Fill with incompressible bytes: iOS doesn't swap, it compresses,
            // and jetsam bills phys_footprint at the *compressed* size — a
            // sparse pattern would collapse under the very memory pressure
            // this drill exists to create. (Also avoids assuming a page size.)
            let words = raw.bindMemory(to: UInt64.self)
            var state = DispatchTime.now().uptimeNanoseconds | 1
            for index in words.indices {
                state ^= state << 13
                state ^= state >> 7
                state ^= state << 17
                words[index] = state
            }
        }
        ballastChunks.append(chunk)
        logger?.logEvent("ballast_mb=\(ballastMB)")
    }

    private func startFeed() {
        feedTask?.cancel()
        let stream = LocationFeed.stream(backend: backend) { diagnostic in
            Task { @MainActor [weak self] in
                self?.logRunEvent("cl_diag \(diagnostic)")
            }
        }
        feedTask = Task { [weak self] in
            for await location in stream {
                self?.ingest(location)
            }
        }
    }

    private func ingest(_ location: CLLocation) {
        gpsSampleCount += 1
        speedKmh = max(location.speed, 0) * 3.6
        speedText = location.speed >= 0 ? String(format: "%.1f", location.speed * 3.6) : "--.-"
        hasFix = location.horizontalAccuracy >= 0
        accuracyText = hasFix ? String(format: "%.0f", location.horizontalAccuracy) : "--"
        // Naive integration with a coarse accuracy gate — S1 measures the raw
        // stack; real filtering is the 0.2.0 MetricsEngine's job (FRO-403).
        if let last = lastLocation,
           location.horizontalAccuracy >= 0, location.horizontalAccuracy < 50 {
            distanceMeters += location.distance(from: last)
            distanceText = String(format: "%.2f", distanceMeters / 1000)
        }
        lastLocation = location
        logger?.updateLatest(location: location, totalSamples: gpsSampleCount)
    }

    private func updateDeviceReadings() {
        batteryText = DeviceReadings.batteryPercentText() ?? "--"
        thermalText = ProcessInfo.processInfo.thermalState.shortLabel
    }
}

