import CoreLocation

enum LocationBackend: String, CaseIterable, Identifiable {
    /// `CLLocationUpdate.liveUpdates(.otherNavigation)` — Apple's named config for
    /// cycling. Cadence is community-observed at 1–2 Hz and undocumented; whether
    /// that is enough for a stable speed display is exactly what S1 measures.
    case liveUpdates
    /// Legacy `CLLocationManager` with `kCLLocationAccuracyBestForNavigation`,
    /// kept for the accuracy/cadence comparison against the modern path.
    case legacyManager

    var id: String { rawValue }
    var label: String { self == .liveUpdates ? "LIVE" : "MGR" }
}

/// One stream shape over both GPS backends so the model can swap them mid-run.
enum LocationFeed {
    /// `onDiagnostic` receives the flag set of location-less updates — that's
    /// where liveUpdates explains a stall (stationary, insufficiently-in-use,
    /// unavailable…), which is exactly what the FRO-394 soak drill needs to
    /// turn "the feed stopped" into a diagnosable finding.
    @MainActor
    static func stream(backend: LocationBackend,
                       onDiagnostic: (@Sendable (String) -> Void)? = nil) -> AsyncStream<CLLocation> {
        switch backend {
        case .liveUpdates:
            AsyncStream { continuation in
                let task = Task {
                    do {
                        // liveUpdates triggers the When-In-Use prompt itself when
                        // authorization is undetermined.
                        for try await update in CLLocationUpdate.liveUpdates(.otherNavigation) {
                            if let location = update.location {
                                continuation.yield(location)
                            } else if let onDiagnostic {
                                var flags: [String] = []
                                if update.isStationary { flags.append("stationary") }
                                if update.insufficientlyInUse { flags.append("insufficientlyInUse") }
                                if update.locationUnavailable { flags.append("locationUnavailable") }
                                if update.authorizationDenied { flags.append("authorizationDenied") }
                                if update.serviceSessionRequired { flags.append("serviceSessionRequired") }
                                onDiagnostic(flags.isEmpty ? "no-location" : flags.joined(separator: "+"))
                            }
                        }
                    } catch {
                        // Spike code: the run keeps going; the gap itself is the signal
                        // (sample counts in the CSV flatline).
                    }
                    continuation.finish()
                }
                continuation.onTermination = { _ in task.cancel() }
            }
        case .legacyManager:
            AsyncStream { continuation in
                let source = LegacyLocationSource(continuation: continuation)
                continuation.onTermination = { _ in
                    Task { @MainActor in source.stop() }
                }
            }
        }
    }
}

/// CLLocationManager wants creation, start/stop, and delegate callbacks on one
/// thread; everything here happens on the main run loop. Delegate methods are
/// nonisolated per the protocol but only touch the Sendable continuation.
@MainActor
private final class LegacyLocationSource: NSObject, CLLocationManagerDelegate {
    private let manager = CLLocationManager()
    private let continuation: AsyncStream<CLLocation>.Continuation

    init(continuation: AsyncStream<CLLocation>.Continuation) {
        self.continuation = continuation
        super.init()
        manager.delegate = self
        manager.desiredAccuracy = kCLLocationAccuracyBestForNavigation
        manager.activityType = .otherNavigation
        // FRO-394: keep the MGR arm delivering while locked (legal with the
        // `location` UIBackgroundMode + When-In-Use; liveUpdates does this
        // implicitly via CLBackgroundActivitySession).
        manager.allowsBackgroundLocationUpdates = true
        manager.pausesLocationUpdatesAutomatically = false
        if manager.authorizationStatus == .notDetermined {
            manager.requestWhenInUseAuthorization()
        }
        manager.startUpdatingLocation()
    }

    func stop() {
        manager.stopUpdatingLocation()
        continuation.finish()
    }

    nonisolated func locationManager(_ manager: CLLocationManager, didUpdateLocations locations: [CLLocation]) {
        for location in locations {
            continuation.yield(location)
        }
    }

    nonisolated func locationManager(_ manager: CLLocationManager, didFailWithError error: Error) {
        // Transient CoreLocation errors (e.g. kCLErrorLocationUnknown) resolve on
        // their own; keep the stream open and let the CSV show the gap.
    }
}

