import SwiftUI

/// S2 workout lab: drives the HKWorkoutSession spike and shows the experiment
/// log live. Spike UI — function over polish, but dark like everything else.
struct WorkoutLabScreen: View {
    @Bindable var controller: WorkoutController
    @Environment(\.dismiss) private var dismiss

    var body: some View {
        NavigationStack {
            List {
                statusSection
                actionsSection
                protocolSection
                eventsSection
            }
            .navigationTitle("S2 Workout Lab")
            .toolbar {
                ToolbarItem(placement: .cancellationAction) {
                    Button("Close") { dismiss() }
                }
                ToolbarItem(placement: .primaryAction) {
                    ShareLink(item: controller.log.fileURL) {
                        Label("Log", systemImage: "square.and.arrow.up")
                    }
                }
            }
        }
        .preferredColorScheme(.dark)
    }

    private var statusSection: some View {
        Section("Status") {
            HarnessListRow("Authorized", controller.isAuthorized ? "yes" : "no")
            HarnessListRow("Session", controller.sessionStateText)
            HarnessListRow("Recovery", controller.recoveryStatusText)
            HarnessListRow("Live Activity", controller.liveActivityActive ? "active" : "off")
            if let error = controller.log.lastError {
                Text(error).foregroundStyle(.red).font(.footnote)
            }
        }
    }

    private var actionsSection: some View {
        Section("Actions") {
            Button("1. Request HealthKit authorization") {
                Task { await controller.requestAuthorization() }
            }
            Button("2. Start cycling workout") {
                Task { await controller.startWorkout() }
            }
            Toggle("Location feed (route)", isOn: $controller.locationFeedEnabled)
            Button("3. Start Live Activity") {
                controller.startLiveActivity()
            }
            Button("Pause") { controller.pauseWorkout() }
            Button("Resume") { controller.resumeWorkout() }
            Button("End workout") {
                Task { await controller.endWorkout() }
            }
            Button("CRASH (recovery drill)", role: .destructive) {
                controller.crash()
            }
        }
    }

    private var protocolSection: some View {
        Section("Device protocol") {
            Text("""
            Q1 (workout runtime): authorize → start workout with location feed \
            OFF → lock the phone for 10 min → unlock, share the log. If \
            `heartbeat` rows continued while locked, workout runtime is general.

            Q2 (LA throttling): start workout + Live Activity → lock 10 min → \
            before unlocking, compare the counter shown on the lock screen with \
            the wall clock; after unlocking, compare `la_update` attempt rows \
            against what the activity displayed.

            Recovery: start workout → CRASH → relaunch → check Status shows \
            "recovered" → End workout → verify the ride in Apple Health \
            (map, distance, HR/power/cadence sine waves).
            """)
            .font(.footnote)
            .foregroundStyle(.secondary)
        }
    }

    private var eventsSection: some View {
        Section("Recent events") {
            ForEach(controller.log.recent.reversed()) { entry in
                HStack(alignment: .firstTextBaseline, spacing: 8) {
                    Text(entry.timestamp, format: .dateTime.hour().minute().second())
                        .font(.caption2.monospaced())
                        .foregroundStyle(.secondary)
                    Text(entry.event)
                        .font(.caption.monospaced().bold())
                    Text(entry.detail)
                        .font(.caption.monospaced())
                        .foregroundStyle(.secondary)
                        .lineLimit(1)
                }
            }
        }
    }

    private func row(_ label: String, _ value: String) -> some View {
        HStack {
            Text(label)
            Spacer()
            Text(value).foregroundStyle(.secondary).font(.body.monospaced())
        }
    }
}

#Preview {
    WorkoutLabScreen(controller: WorkoutController())
}

